style.css:
@-moz-document domain("open.spotify.com") {
/* MAIN BACKGROUND (THIS IS THE REAL FIX) */
.main-view-container__scroll-node {
    background-image: 
        url("https://cdn.shopify.com/s/files/1/0568/2298/8958/files/sanrio_characters_cinnamoroll_3.png"),
        linear-gradient(rgba(200,230,255,0.6), rgba(200,230,255,0.6)) !important;

    background-size: contain !important; /* FULL IMAGE */
    background-repeat: no-repeat !important;
    background-position: center !important;
}

/* REMOVE DARK OVERLAY */
.main-view-container__scroll-node-child {
    background: transparent !important;
}

/* SIDEBAR */
.Root__nav-bar {
    background: rgba(255,255,255,0.5) !important;
}

/* MAIN AREA GLASS EFFECT */
.main-view-container,
.Root__main-view {
    background: rgba(255,255,255,0.3) !important;
    backdrop-filter: blur(8px);
}

/* CARDS */
.main-card-card {
    background: rgba(255,255,255,0.5) !important;
    border-radius: 15px !important;
}

/* PLAYER BAR */
.now-playing-bar-container {
    background: rgba(255,255,255,0.5) !important;
    backdrop-filter: blur(10px);
}

/* TEXT */
* {
    color: #3a4a5a !important;
}

/* BUTTONS */
button {
    background: #aee1ff !important;
    border-radius: 20px !important;
}

/* SCROLL FIX */
html, body {
    background: transparent !important;
}
}
